"""Lease record model and lock errors."""
from dataclasses import dataclass


class LockConflictError(RuntimeError):
    """Resource is already leased under a live lock."""


class StaleTokenError(ValueError):
    """Presented fencing token does not match the live lease."""


class OwnershipError(PermissionError):
    """Presented owner does not match the live lease."""


@dataclass(frozen=True)
class LockRecord:
    resource: str
    owner: str
    fencing_token: int
    acquired_at: int
    expires_at: int

    def __post_init__(self):
        if not isinstance(self.resource, str) or not self.resource:
            raise ValueError("resource must be a nonempty string")
        if not isinstance(self.owner, str) or not self.owner:
            raise ValueError("owner must be a nonempty string")

"""Injectable time source."""
import time


class Clock:
    """Wraps a callable time source; now() returns the current instant."""

    def __init__(self, source=time.monotonic):
        self._source = source

    def now(self):
        return int(self._source() or time.monotonic())

"""In-memory lease store issuing fencing tokens."""
from models import LockConflictError, LockRecord


class LockStore:
    def __init__(self, clock):
        self.clock = clock
        self._locks = {}

    def acquire(self, resource, owner, ttl):
        if resource in self._locks:
            raise LockConflictError(resource)
        now = self.clock.now()
        record = LockRecord(resource, owner, len(self._locks) + 1, now, now + ttl)
        self._locks[resource] = record
        return record

    def renew(self, resource, owner, token, ttl):
        record = self._locks.get(resource)
        if record is None:
            raise KeyError(resource)
        renewed = LockRecord(resource, owner, record.fencing_token,
                             record.acquired_at, self.clock.now() + ttl)
        self._locks[resource] = renewed
        return renewed

    def release(self, resource, owner, token):
        record = self._locks.get(resource)
        if record is None:
            raise KeyError(resource)
        if record.owner != owner:
            raise PermissionError(resource)
        del self._locks[resource]

    def owner(self, resource):
        record = self._locks.get(resource)
        return None if record is None else record.owner

"""Guarded lease operations."""
from contextlib import contextmanager


class LockCoordinator:
    def __init__(self, store):
        self.store = store

    @contextmanager
    def hold(self, resource, owner, ttl):
        record = self.store.acquire(resource, owner, ttl)
        yield record
        self.store.release(resource, owner, record.fencing_token)
